CREATE TABLE IF NOT EXISTS gis_source_checks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES gis_data_sources(id) ON DELETE CASCADE, check_type text NOT NULL, checked_at timestamptz NOT NULL DEFAULT now(), http_status integer, reachable boolean NOT NULL DEFAULT false, content_type text, response_summary text, checked_url text, status text NOT NULL DEFAULT 'Recorded');
CREATE TABLE IF NOT EXISTS gis_analysis_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, requested_by_reference text, requested_at timestamptz NOT NULL DEFAULT now(), analysis_scope text NOT NULL DEFAULT 'Pilot', status text NOT NULL DEFAULT 'Queued', completed_at timestamptz, summary text);
CREATE TABLE IF NOT EXISTS gis_analysis_findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES gis_analysis_requests(id) ON DELETE CASCADE, analysis_type text NOT NULL, layer_id uuid REFERENCES gis_layers(id) ON DELETE SET NULL, result_status text NOT NULL DEFAULT 'Pending', severity text NOT NULL DEFAULT 'Info', finding text, evidence_reference text, confidence_score numeric(6,2), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_source_checks_source ON gis_source_checks(source_id,checked_at DESC);
CREATE INDEX IF NOT EXISTS idx_gis_analysis_requests_asset ON gis_analysis_requests(asset_id,requested_at DESC);
CREATE INDEX IF NOT EXISTS idx_gis_analysis_findings_request ON gis_analysis_findings(request_id,result_status,severity);